mapper.update:
UPDATE tracking.service_case_answer
   SET customer_response = #{customerResponse},
       customer_responded_at = #{customerRespondedAt}
 WHERE case_number = #{caseNumber}
   AND answer_no = #{answerNo}
   AND customer_response IS NULL

mapper.select:
SELECT case_number FROM tracking.service_case
 WHERE status NOT IN ('CLOSED', 'DUPLICATE_CLOSED')
   AND cause = #{cause}

    AND shipper_company_id = #{shipperCompanyId}
    AND shipper_company_id IS NULL


    AND booking_id = #{bookingId}
    AND booking_id IS NULL

 ORDER BY created_at, case_number
 FETCH FIRST 1 ROWS ONLY
